const profileLink = document.querySelector('[data-testid=AppTabBar_Profile_Link]');
const href = profileLink?.getAttribute('href') ?? null;
const handle = href ? href.replace(/^\//, '') : null;
const displayName = document.querySelector('[data-testid=SideNav_AccountSwitcher_Button] [dir]')?.innerText?.split('\n')[0] ?? null;
return { handle, display_name: displayName, profile_url: handle ? `https://x.com/${handle}` : null };

const limit = args.limit ?? 10;
const articles = Array.from(document.querySelectorAll('article[data-testid=tweet]')).slice(0, limit);
function count(article, testid) {
  const btn = article.querySelector(`[data-testid=${testid}]`);
  if (!btn) return null;
  const t = btn.innerText.trim();
  return t || '0';
}
function parsePermalink(article) {
  const a = article.querySelector('a[href*="/status/"]');
  if (!a) return { handle: null, status_id: null, url: null };
  const href = a.getAttribute('href');
  const m = href.match(/^\/([^/]+)\/status\/(\d+)/);
  return { handle: m?.[1] ?? null, status_id: m?.[2] ?? null, url: m ? `https://x.com${href}` : null };
}
const out = articles.map((a, i) => {
  const text = a.querySelector('[data-testid=tweetText]')?.innerText ?? '';
  const time = a.querySelector('time')?.getAttribute('datetime') ?? null;
  const link = parsePermalink(a);
  return {
    index: i,
    text: text.slice(0, 500),
    author_handle: link.handle,
    posted_at: time,
    url: link.url,
    status_id: link.status_id,
    counts: { reply: count(a, 'reply'), retweet: count(a, 'retweet'), like: count(a, 'unlike') ?? count(a, 'like') },
    liked: !!a.querySelector('[data-testid=unlike]')
  };
});
return { page: location.pathname, count: out.length, tweets: out };

if (!/\/status\/\d+/.test(location.pathname)) {
  return { error: 'not on a tweet status page', current: location.pathname, hint: 'call /x_open_tweet { handle, id } first' };
}
const limit = args.limit ?? 20;
const arts = Array.from(document.querySelectorAll('article[data-testid=tweet]')).slice(0, limit);
const parsed = arts.map((a, i) => {
  const link = a.querySelector('a[href*="/status/"]')?.getAttribute('href') ?? '';
  const m = link.match(/^\/([^/]+)\/status\/(\d+)/);
  return {
    index: i,
    text: a.querySelector('[data-testid=tweetText]')?.innerText?.slice(0, 500) ?? '',
    author: m?.[1] ?? null,
    status_id: m?.[2] ?? null,
    posted_at: a.querySelector('time')?.getAttribute('datetime') ?? null,
    liked: !!a.querySelector('[data-testid=unlike]')
  };
});
return { url: location.href, count: parsed.length, tweets: parsed };

const h = String(args.handle ?? '').replace(/^@/, '').trim();
if (!h) return { error: 'handle required' };
location.assign('/' + encodeURIComponent(h));
return { navigating_to: '/' + h };

let target = args.url;
if (!target && args.handle && args.id) {
  target = `/${String(args.handle).replace(/^@/, '')}/status/${args.id}`;
}
if (!target) return { error: 'need { url } or { handle, id }' };
location.assign(target);
return { navigating_to: target };

const q = String(args.query ?? '').trim();
if (!q) return { error: 'query required' };
const tab = args.tab ?? 'top';
const f = tab === 'latest' ? '&f=live' : tab === 'people' ? '&f=user' : tab === 'photos' ? '&f=image' : tab === 'videos' ? '&f=video' : '';
const url = `/search?q=${encodeURIComponent(q)}&src=typed_query${f}`;
location.assign(url);
return { navigating_to: url };

async function waitFor(selectorFn, timeoutMs) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const el = selectorFn();
    if (el) return el;
    await new Promise(r => setTimeout(r, 80));
  }
  return null;
}
const text = String(args.text ?? '');
if (!text) return { error: 'text required' };
let textarea = document.querySelector('[data-testid=tweetTextarea_0]');
if (!textarea) {
  const btn = document.querySelector('[data-testid=SideNav_NewTweet_Button]');
  if (!btn) return { error: 'no compose button and no inline textarea — try /x_open_home first' };
  btn.click();
  textarea = await waitFor(() => document.querySelector('[data-testid=tweetTextarea_0]'), 3000);
  if (!textarea) return { error: 'compose modal did not open within 3s' };
}
textarea.focus();
// DraftJS contenteditable — execCommand is still the most reliable insertion path.
document.execCommand('insertText', false, text);
return { ok: true, char_count: text.length, post_button_visible: !!document.querySelector('[data-testid=tweetButton], [data-testid=tweetButtonInline]') };

const btn = document.querySelector('[data-testid=tweetButton]:not([aria-disabled=true])') || document.querySelector('[data-testid=tweetButtonInline]:not([aria-disabled=true])');
if (!btn) {
  const anyBtn = document.querySelector('[data-testid=tweetButton], [data-testid=tweetButtonInline]');
  return { error: 'no enabled post button found', any_button_visible: !!anyBtn, hint: 'maybe the draft is empty or the button is disabled (rate limit, login wall)' };
}
btn.click();
return { clicked: true, button_testid: btn.getAttribute('data-testid') };

const idx = args.index ?? 0;
const action = args.action ?? 'toggle';
const articles = document.querySelectorAll('article[data-testid=tweet]');
const article = articles[idx];
if (!article) return { error: `no tweet at index ${idx}`, available_count: articles.length };
const likeBtn = article.querySelector('[data-testid=like]');
const unlikeBtn = article.querySelector('[data-testid=unlike]');
const isLiked = !!unlikeBtn;
let btn;
if (action === 'like') btn = isLiked ? null : likeBtn;
else if (action === 'unlike') btn = isLiked ? unlikeBtn : null;
else btn = unlikeBtn || likeBtn;
if (!btn) return { ok: true, no_op: true, already: isLiked ? 'liked' : 'unliked', action };
btn.click();
return { ok: true, clicked: btn.getAttribute('data-testid'), was_liked: isLiked, now_liked: !isLiked };
